import { number, percent } from '../format.js'
defineProps({ metrics: Object })
</script>
<template><div class="metrics"><div class="metric"><span>初始{{ metrics.simulated ? '模拟作业成本' : '拣货距离' }}</span><strong>{{ number(metrics.baselineDistance) }} <small>{{ metrics.simulated ? '加权等效米' : '米' }}</small></strong></div><div class="metric"><span>当前{{ metrics.simulated ? '模拟作业成本' : '拣货距离' }}</span><strong>{{ number(metrics.currentDistance) }} <small>{{ metrics.simulated ? '加权等效米' : '米' }}</small></strong></div><div class="metric"><span>改善率</span><strong :class="metrics.improvement < 0 ? 'error' : 'success'">{{ percent(metrics.improvement, true) }}</strong></div></div><p v-if="metrics.simulated" class="rule">库存 {{ metrics.stockCartons }}箱 · 占用 {{ metrics.occupiedSlots }}/{{ metrics.availableSlots ?? metrics.totalSlots }} 个可用货位 · 可用货位占用率 {{ percent(metrics.availableUtilization ?? metrics.utilization) }}（不是体积利用率） · 全仓{{ metrics.totalSlots }}位，其中{{ metrics.disabledSlots ?? 0 }}位不可用<br><span v-for="(rate,i) in (metrics.levelAvailableUtilization ?? metrics.levelUtilization)" :key="i">第{{ i+1 }}层 {{ metrics.levelAvailableSlots?.[i] === 0 ? '无可用货位' : percent(rate) }}　</span></p></template>
